public static void Main(Args _args)
{
    RRBBookInventoryUpdationController controller = RRBBookInventoryUpdationController::Construct();                

    controller.initFromFromBookFormIfNeeded(_args);

    if(controller.prompt())
    {
        controller.runOperation();
    }
}

public void new(IdentifierName _className = '',
    IdentifierName _methodName = '',
    SysOperationExecutionMode _executionMode = SysOperationExecutionMode::Asynchronous)
{
    super(_className, _methodName, _executionMode);
}

public void initFromFromBookFormIfNeeded(Args _args)
{
    FormRun callerformRun = _args.caller();

    if(callerformRun
        && callerformRun.name() == formStr(RRBBook))
    {
        RRBBookTable bookActiveRecord = callerformRun.dataSource(formDataSourceStr(RRBBook, RRBBookTable)).cursor();

        RRBBookInventoryUpdationDataContract contract = this.getDataContract();

        contract.parmBookId(bookActiveRecord.Id);
    }
}

public static RRBBookInventoryUpdationController Construct(SysOperationExecutionMode _executionMode = SysOperationExecutionMode::Asynchronous)
{
    RRBBookInventoryUpdationController controller = new RRBBookInventoryUpdationController(classStr(RRBBookInventoryUpdationService),
    methodStr(RRBBookInventoryUpdationService, runProcess),
    _executionMode);

    controller.parmDialogCaption("@ITFormacion:UpdateBookInventory");

    return controller;
}

public boolean validateParameters()
{
    boolean ret;

    ret = super();


    if(ret)
    {
        RRBBookInventoryUpdationDataContract dataContract = this.getDataContract();
        ret = this.validateBook(dataContract.parmBookId())
            && this.validateNewQty(dataContract.parmNewQty());
    }

    return ret;
}

public boolean validateBook(RRBId _bookId)
{
    if(!RRBBookTable::exist(_bookId))
    {
        return checkFailed(strFmt("@ITFormacion:Book1DoesNotExist", _bookId));
    }

    return true;
}

public boolean validateNewQty(Qty _newQty)
{
    if(_newQty < 0)
    {
        return checkFailed("@ITFormacion:TransactionWouldMakeTheTotalNegative");
    }

    return true;
}
